function visit(items, fn) {
  for (const item of items) {
    fn(item);
    if (item.children) visit(item.children, fn);
  }
}

/** Gathers the distinct tags of a tree, then loads each one once. */
export async function gather(items, load) {
  const seen = new Set();
  visit(items, (n) => n.tag && seen.add(n.tag));
  const loaded = await Promise.all([...seen].map(async (tag) => [tag, await load(tag)]));
  return Object.fromEntries(loaded);
}
EOF
