import { test } from 'node:test';
import assert from 'node:assert/strict';
import { gather } from './collect.mjs';

test('a Set filled by a callback and spread once yields every element', async () => {
  const tree = [{ tag: 'a', children: [{ tag: 'b' }, { tag: 'a' }] }];
  const calls = [];
  const out = await gather(tree, async (t) => { calls.push(t); return t.toUpperCase(); });
  assert.deepEqual(out, { a: 'A', b: 'B' });
  assert.deepEqual(calls, ['a', 'b']);
});
EOF
